import{_ as r,a0 as s,w as p,s as u,ao as e,I as i,a1 as a,A as l,x as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const g=JSON.parse('{"title":"图解 Rocky Linux 9 安装步骤 | LCTT x X-CMD","titleTemplate":false,"description":"图解 Rocky Linux 9 安装步骤 | LCTT (202208) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"图解 Rocky Linux 9 安装步骤 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"图解 Rocky Linux 9 安装步骤 | LCTT (202208) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202208/20220718 How to Install Rocky Linux 9 Step by Step with Screenshots","title":"图解 Rocky Linux 9 安装步骤","tag":"202208","desc":""},"relativePath":"202208/20220718 How to Install Rocky Linux 9 Step by Step with Screenshots.md","filePath":"[post].md"}'),c={name:"202208/20220718 How to Install Rocky Linux 9 Step by Step with Screenshots.md"};function y(h,t,d,x,k,b){const o=s("Link");return p(),u("div",null,[t[17]||(t[17]=e('<h1 id="图解-rocky-linux-9-安装步骤" tabindex="-1">图解 Rocky Linux 9 安装步骤 <a class="header-anchor" href="#图解-rocky-linux-9-安装步骤" aria-label="Permalink to “图解 Rocky Linux 9 安装步骤”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202208/08/172822s7zwhj7wuzzjfm25.jpg" alt=""></p><blockquote><p>这篇教程中，我们将图解 Rocky Linux 9 安装步骤。</p></blockquote><p><ruby>Rocky 企业软件基金会<rt>Rocky Enterprise Software Foundation</rt></ruby> 已经发布了它的最新的操作系统 “Rocky Linux 9”。Rocky Linux 是针对工作站和服务器的自由而开源的操作系统。它被认为是 CentOS Linux 的继承者。</p><p>Rocky Linux 9 是 RHEL 9 的复制品，其开发代号是“Blue Onyx”。Rocky Linux 和 RHEL 之间的主要不同是，它有它自己的名为 “Peridot” 的开源构建系统。</p><h3 id="rocky-linux-9-的更新和特色" tabindex="-1">Rocky Linux 9 的更新和特色 <a class="header-anchor" href="#rocky-linux-9-的更新和特色" aria-label="Permalink to “Rocky Linux 9 的更新和特色”">​</a></h3><ul><li>Gnome 40 是默认的桌面环境</li><li>在 XFS 文件系统上支持<ruby>直接访问<rt>Direct Access</rt></ruby>（DAX）操作</li><li>更新了运行时和编译器，如 GCC 11.2.1 、LLVM 13.0.1 、Rust 1.58.1 和 Go 1.17.1</li><li>更新了开发工具链，如 Python 3.9 、Node.js 16 、Ruby 3.0.3 、Perl 5.32 和 PHP 8.0</li><li>ssh 默认禁用了 root 用户身份验证</li><li>更新了 OpenSSL 3.0，改进了 Cockpit 网页主控台</li><li>社区提供支持到 2032 年 05 月 31 日</li></ul><h3 id="前置条件" tabindex="-1">前置条件 <a class="header-anchor" href="#前置条件" aria-label="Permalink to “前置条件”">​</a></h3><ul><li>2 GB 及更多的内存</li><li>2 个 CPU 核心（1.1 GHz 及更高)</li><li>20 GB 硬盘空间</li><li>可启动介质（USD 或 DVD）</li><li>互联网连接（可选）</li></ul><p>不再耽误时间，让我们直接进入 Rocky Linux 9 的安装步骤：</p><h3 id="_1、下载-rocky-linux-9-的-iso-文件" tabindex="-1">1、下载 Rocky Linux 9 的 ISO 文件 <a class="header-anchor" href="#_1、下载-rocky-linux-9-的-iso-文件" aria-label="Permalink to “1、下载 Rocky Linux 9 的 ISO 文件”">​</a></h3><p>使用下面的官方网址来下载 ISO 文件</p>',12)),i("blockquote",null,[i("p",null,[i("strong",null,[a(o,{href:"https://rockylinux.org/download"},{default:l(()=>[...t[0]||(t[0]=[n("Rocky Linux 9 ISO",-1)])]),_:1})])])]),t[18]||(t[18]=i("p",null,"在你下载 ISO 文件后，使用已下载的 ISO 文件制作一个可启动介质（USB/DVD）。",-1)),t[19]||(t[19]=i("p",null,"在 Windows 中，你可以利用 Rufus 软件来使用 ISO 文件来制作可启动 USB 驱动器。在 Linux 中，参考下面的内容：",-1)),i("blockquote",null,[i("p",null,[i("strong",null,[a(o,{href:"https://www.linuxtechi.com/create-bootable-usb-disk-dvd-ubuntu-linux-mint/"},{default:l(()=>[...t[1]||(t[1]=[n("在 Ubuntu / Linux Mint 上，如何创建可启动 USB 驱动器",-1)])]),_:1})])])]),t[20]||(t[20]=e(`<h3 id="_2、使用可启动媒介盘启动系统" tabindex="-1">2、使用可启动媒介盘启动系统 <a class="header-anchor" href="#_2、使用可启动媒介盘启动系统" aria-label="Permalink to “2、使用可启动媒介盘启动系统”">​</a></h3><p>在你计划安装 Rocky Linux 9 的硬件系统上，BIOS 设置中将可启动介质从硬盘驱动器更改为 USB 驱动器, 重新启动它。</p><p>在硬件系统使用可启动介质启动后，我们将看到下面的屏幕，</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/07/Select-Install-Rocky-Linux-9-option.png" alt="Select-Install-Rocky-Linux-9-option"></p><p>选择第一个选项， <ruby>安装 Rocky Linux 9.0<rt>Install Rocky Linux 9.0</rt></ruby> ，并按下 <ruby>回车<rt>enter</rt></ruby> 按键。</p><h3 id="_3、选择首选语言" tabindex="-1">3、选择首选语言 <a class="header-anchor" href="#_3、选择首选语言" aria-label="Permalink to “3、选择首选语言”">​</a></h3><p>选择<strong>安装过程</strong>的首选语言，然后单击 <ruby>继续<rt>Continue</rt></ruby> 按钮，</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/07/Preferred-Language-for-RockyLinux9-Installation.png" alt="Preferred-Language-for-RockyLinux9-Installation"></p><h3 id="_4、安装过程摘要" tabindex="-1">4、安装过程摘要 <a class="header-anchor" href="#_4、安装过程摘要" aria-label="Permalink to “4、安装过程摘要”">​</a></h3><p>在这个步骤中，我们将看到如下的初始安装摘要。要开始安装，首先，我们必须完成标记项目，如 <ruby>安装目标<rt>Installation Destination</rt></ruby> 和 <ruby>用户设置<rt>User settings</rt></ruby>。</p><p>除了已标记的项目外，我们也可以更改现有的项目，只需要按照你的要求单击它们就可以进行更改。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/07/Initial-Installation-Summary-Rocky-Linux9.png" alt="Initial-Installation-Summary-Rocky-Linux9"></p><h4 id="配置安装目标" tabindex="-1">配置安装目标 <a class="header-anchor" href="#配置安装目标" aria-label="Permalink to “配置安装目标”">​</a></h4><p>在这个项目中，我们将为 Rocky Linux 具体指定分区方案。单击 <ruby>安装目标<rt>Installation Destination</rt></ruby>。</p><p>在这里，我们可以为 <ruby>存储配置<rt>storage configuration</rt></ruby> 或 <ruby>分区方案<rt>partition scheme</rt></ruby> 选择 <ruby>自动<rt>automatic</rt></ruby> 选项或 <ruby>自定义<rt>custom </rt></ruby> 选项。</p><p>在自动选项中，安装程序将在磁盘上自动地创建分区，而自定义选项允许我们在磁盘上手动创建分区。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/07/Choose-custom-Storage-Configuration-Rocky-Linux9.png" alt="Choose-custom-Storage-Configuration-Rocky-Linux9"></p><p>在这篇指南中，我将使用 <ruby>自定义<rt>Custom</rt></ruby> 选项，单击 <ruby>执行<rt>Done</rt></ruby> 按钮。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/07/Standard-Partition-Scheme-RockyLinux9.png" alt="Standard-Partition-Scheme-RockyLinux9"></p><p>在该 40 GB 的磁盘上，我们将创建以下分区，</p><ul><li><code>/boot</code>：2GB（xfs 文件系统）</li><li><code>/</code>：10 GB（xfs 文件系统）</li><li><code>/home</code>：25 GB（xfs 文件系统）</li><li>交换分区：2 GB</li></ul><p>开始创建分区，选择 <ruby>标准分区<rt>Standard Partition</rt></ruby> 方案，然后单击 “+” 符号。</p><p>创建第一个分区，大小为 2 GB 的 <code>/boot</code> 分区，</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/07/Boot-Partition-RockyLinux9-Installation.png" alt="Boot-Partition-RockyLinux9-Installation"></p><p>单击 <ruby>添加挂载点<rt>Add mount point</rt></ruby> 按钮。</p><p>类似地，接下来分别创建大小为 10 GB 的 <code>/</code> 分区和 25 GB 的 <code>/home</code> 分区。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/07/Slash-Partition-Rocky-Linux9-installation.png" alt="Slash-Partition-Rocky-Linux9-installation"></p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/07/Home-Partition-Rocky-Linux9-Installation.png" alt="Home-Partition-Rocky-Linux9-Installation"></p><p>现在，创建最后一个分区，大小为 2 GB 的交换分区，（LCTT 校注：如果你的内存非常多，你可以选择不创建交换分区。另外，对于生产环境，建议将存储数据的目录单独划分分区。）</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/07/Swap-Partition-RockyLinux9-Installation.png" alt="Swap-Partition-RockyLinux9-Installation"></p><p>在你完成手动分区后，单击 <ruby>执行<rt>Done</rt></ruby> 按钮来完成这个项目。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/07/Finish-Manual-Partitioning-RockyLinux9-Installation.png" alt="Finish-Manual-Partitioning-RockyLinux9-Installation"></p><p>选择 <ruby>接受更改<rt>Accept Changes</rt></ruby> 按钮来将这些更改写入磁盘。它也将返回到安装摘要屏幕。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/07/Accept-Changes-to-Write-on-Disk-RockyLinux9.png" alt="Accept-Changes-to-Write-on-Disk-RockyLinux9"></p><h4 id="配置用户设置" tabindex="-1">配置用户设置 <a class="header-anchor" href="#配置用户设置" aria-label="Permalink to “配置用户设置”">​</a></h4><p>在 <ruby>用户设置<rt>User Settings</rt></ruby> 下，单击 <ruby>root 密码 <rt>Root Password</rt></ruby> 按钮。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/07/Set-Root-Password-RockyLinux9-Instalation.png" alt="Set-Root-Password-RockyLinux9-Instalation"></p><p>设置 root 用户的密码，并单击 <ruby>执行<rt>Done</rt></ruby> 按钮。</p><p>再次回到 <ruby>用户设置<rt>User Settings</rt></ruby> 下，单击 <ruby>用户创建<rt>User Creation</rt></ruby> 按钮，具体指定本地用户的详细信息，例如用户名称和密码。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/07/Local-User-Create-During-RockyLinux9-Installation.png" alt="Local-User-Create-During-RockyLinux9-Installation"></p><p>单击 <ruby>执行<rt>Done</rt></ruby> 按钮，它也将返回到安装摘要。</p><p>现在，我们准备开始安装，单击<ruby>开始安装<rt>Begin Installation</rt></ruby> 按钮，</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/07/Begin-Installation-Option-RockyLinux9.png" alt="Begin-Installation-Option-RockyLinux9"></p><h3 id="_5、安装过程开始" tabindex="-1">5、安装过程开始 <a class="header-anchor" href="#_5、安装过程开始" aria-label="Permalink to “5、安装过程开始”">​</a></h3><p>在这一步骤中，安装程序已经开始了，并在正在进行中，</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/07/RockyLinux9-Installation-Progress.png" alt="RockyLinux9-Installation-Progress"></p><p>在安装过程完成后，安装程序将提示你重新启动系统。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/07/Reboot-System-after-RockyLinux9-Installation.png" alt="Reboot-System-after-RockyLinux9-Installation"></p><p>单击 <ruby>重新启动系统<rt>Reboot System</rt></ruby> 按钮。</p><p>注意：不要忘记在 BIOS 设置中将可启动介质从 USB 启动更改为硬盘驱动器启动。</p><h3 id="_6、安装后的登录屏幕和桌面环境" tabindex="-1">6、安装后的登录屏幕和桌面环境 <a class="header-anchor" href="#_6、安装后的登录屏幕和桌面环境" aria-label="Permalink to “6、安装后的登录屏幕和桌面环境”">​</a></h3><p>在成功安装后，当系统启动时，我们将看到下面的登录屏幕：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/07/RockyLinux9-Loginscreen-Post-Installation.png" alt="RockyLinux9-Loginscreen-Post-Installation"></p><p>使用我们在安装期间创建的用户名称和密码，按下 <ruby>回车<rt>enter</rt></ruby> 按键来登录。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/07/Desktop-Env-RockyLinux9.png" alt="Desktop-Env-RockyLinux9"></p><p>打开终端，依次运行下面的命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install epel-release -y</span></span>
<span class="line"><span>$ sudo dnf install neofetch -y</span></span></code></pre></div><p>现在，来验证系统的详细信息，运行 <code>neofetch</code> 命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ neofetch</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/07/neofetch-rockylinux9-post-installation.png" alt="neofetch-rockylinux9-post-installation"></p><p>这就是这篇指南的全部内容，我希望它对你有用。请在下面的评论区贴出你的疑问和反馈。</p><hr>`,62)),i("p",null,[t[3]||(t[3]=n("via: ",-1)),a(o,{href:"https://www.linuxtechi.com/how-to-install-rocky-linux-9-step-by-step/"},{default:l(()=>[...t[2]||(t[2]=[n("https://www.linuxtechi.com/how-to-install-rocky-linux-9-step-by-step/",-1)])]),_:1})]),i("p",null,[t[8]||(t[8]=n("作者：",-1)),a(o,{href:"https://www.linuxtechi.com/author/pradeep/"},{default:l(()=>[...t[4]||(t[4]=[n("Pradeep Kumar",-1)])]),_:1}),t[9]||(t[9]=n(" 选题：",-1)),a(o,{href:"https://github.com/lkxed"},{default:l(()=>[...t[5]||(t[5]=[n("lkxed",-1)])]),_:1}),t[10]||(t[10]=n(" 译者：",-1)),a(o,{href:"https://github.com/robsean"},{default:l(()=>[...t[6]||(t[6]=[n("robsean",-1)])]),_:1}),t[11]||(t[11]=n(" 校对：",-1)),a(o,{href:"https://github.com/wxy"},{default:l(()=>[...t[7]||(t[7]=[n("wxy",-1)])]),_:1})]),i("p",null,[t[14]||(t[14]=n("本文由 ",-1)),a(o,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...t[12]||(t[12]=[n("LCTT",-1)])]),_:1}),t[15]||(t[15]=n(" 原创编译，",-1)),a(o,{href:"https://linux.cn/"},{default:l(()=>[...t[13]||(t[13]=[n("Linux中国",-1)])]),_:1}),t[16]||(t[16]=n(" 荣誉推出",-1))])])}const L=r(c,[["render",y]]);export{g as __pageData,L as default};
